    while (four != nullptr && four->value != 4) {
        four = four->next;
    }
    if (four != nullptr) {
        four->next = new Node{5, four->next};
    }
    std::cout << "insert 5 after 4: ";
    printList(head);

    head = removeValue(head, 2);
    std::cout << "delete 2: ";
    printList(head);

    head = removeValue(head, 1);
    std::cout << "delete 1: ";
    printList(head);

    freeList(head);
    return 0;
