steps.body:
A list has no index, so finding the middle seems to need two passes. Two pointers at different speeds do it in one: `slow` moves one node per step and `fast` moves two. When `fast` reaches the end, `slow` is halfway.

```cpp
Node* middleNode(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}
```

Check `fast != nullptr` before `fast->next`, in that order, so you never dereference `nullptr`. For an even length this returns the second middle (4 in 1..6).

The same pair detects a cycle, a `next` that points back to an earlier node. This is **Floyd's cycle detection**. Without a cycle `fast` reaches `nullptr`. With one, `fast` gains one node per step inside the loop and lands on `slow`. Comparing the pointers with `==` is safe, but never print them. It needs O(1) extra memory, unlike a set of visited nodes.

A cycle breaks every walk that waits for `nullptr`, `freeList` included: it would read freed nodes and delete one twice, which is undefined behavior. Keep the `tail` pointer and set `tail->next = nullptr;` before freeing.

example.code:
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
};

Node* buildList(const std::vector<int>& values) {
    Node* head = nullptr;
    Node* tail = nullptr;
    for (int v : values) {
        Node* node = new Node{v, nullptr};
        if (head == nullptr) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }
    return head;
}

void freeList(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

Node* middleNode(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

bool hasCycle(const Node* head) {
    const Node* slow = head;
    const Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            return true;
        }
    }
    return false;
}

int main() {
    Node* odd = buildList({1, 2, 3, 4, 5});
    Node* even = buildList({1, 2, 3, 4, 5, 6});
    std::cout << "middle of 1..5: " << middleNode(odd)->value << '\n';
    std::cout << "middle of 1..6: " << middleNode(even)->value << '\n';
    freeList(odd);
    freeList(even);

    Node* head = buildList({1, 2, 3, 4});
    Node* tail = head;
    while (tail->next != nullptr) {
        tail = tail->next;
    }
    std::cout << "before linking: " << (hasCycle(head) ? "cycle" : "no cycle") << '\n';
    tail->next = head->next;
    std::cout << "tail to node 2: " << (hasCycle(head) ? "cycle" : "no cycle") << '\n';
    tail->next = nullptr;
    std::cout << "after breaking: " << (hasCycle(head) ? "cycle" : "no cycle") << '\n';

    freeList(head);
    return 0;
}

